import fs from 'fs';
import http from 'http';
import path from 'path';
import { watch, FSWatcher } from 'chokidar';
import { WebSocketServer, WebSocket } from 'ws';
import { buildSite } from './index';

export const RELOAD_MESSAGE = 'reload';

export const LIVE_RELOAD_SCRIPT = `<script>
(function () {
  var socket = new WebSocket('ws://' + window.location.host);
  socket.addEventListener('message', function (event) {
    if (event.data === '${RELOAD_MESSAGE}') {
      window.location.reload();
    }
  });
})();
</script>`;

export interface ServeOptions {
  contentDir?: string;
  outputDir?: string;
  templatesDir?: string;
  port?: number;
  host?: string;
  debounce?: number;
}

export interface DevServer {
  server: http.Server;
  port: number;
  contentDir: string;
  outputDir: string;
  templatesDir: string;
  watcher: FSWatcher;
  close(): Promise<void>;
}

const CONTENT_TYPES: Record<string, string> = {
  '.html': 'text/html; charset=utf-8',
  '.htm': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'application/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.ico': 'image/x-icon',
  '.txt': 'text/plain; charset=utf-8',
  '.md': 'text/markdown; charset=utf-8',
};

export function injectLiveReloadScript(
  html: string,
  script: string = LIVE_RELOAD_SCRIPT
): string {
  if (/<\/body>/i.test(html)) {
    return html.replace(/<\/body>/i, script + '\n</body>');
  }
  return html + '\n' + script;
}

function isHtml(filePath: string): boolean {
  const ext = path.extname(filePath).toLowerCase();
  return ext === '.html' || ext === '.htm';
}

function contentTypeFor(filePath: string): string {
  const ext = path.extname(filePath).toLowerCase();
  return CONTENT_TYPES[ext] ?? 'application/octet-stream';
}

function createRequestHandler(outputDir: string): http.RequestListener {
  return (req, res) => {
    const rawPath = (req.url ?? '/').split('?')[0];
    let pathname: string;
    try {
      pathname = decodeURIComponent(rawPath);
    } catch {
      res.writeHead(400);
      res.end('Bad request');
      return;
    }

    const relative = pathname === '/' ? 'index.html' : pathname.replace(/^\/+/, '');
    const filePath = path.resolve(outputDir, relative);

    if (filePath !== outputDir && !filePath.startsWith(outputDir + path.sep)) {
      res.writeHead(403);
      res.end('Forbidden');
      return;
    }

    if (!fs.existsSync(filePath) || !fs.statSync(filePath).isFile()) {
      res.writeHead(404);
      res.end('Not found');
      return;
    }

    let body = fs.readFileSync(filePath);
    if (isHtml(filePath)) {
      body = Buffer.from(injectLiveReloadScript(body.toString('utf8')));
    }

    res.writeHead(200, { 'Content-Type': contentTypeFor(filePath) });
    res.end(body);
  };
}

function broadcast(wss: WebSocketServer, message: string): void {
  for (const client of wss.clients) {
    if (client.readyState === WebSocket.OPEN) {
      client.send(message);
    }
  }
}

/**
 * Start a live-reload development server.
 *
 * Performs an initial build, serves the generated site from outputDir over
 * HTTP, injects a WebSocket client script into HTML responses, watches the
 * content and templates directories for changes, rebuilds on change, and tells
 * connected browsers to reload when a rebuild completes.
 */
export async function startDevServer(options: ServeOptions = {}): Promise<DevServer> {
  const contentDir = path.resolve(options.contentDir ?? 'content');
  const outputDir = path.resolve(options.outputDir ?? 'dist');
  const templatesDir = path.resolve(options.templatesDir ?? 'templates');
  const host = options.host ?? '127.0.0.1';
  const port = options.port ?? 3000;
  const debounce = options.debounce ?? 100;

  buildSite({ contentDir, outputDir, templatesDir });

  const server = http.createServer(createRequestHandler(outputDir));
  const wss = new WebSocketServer({ server });

  const watcher = watch([contentDir, templatesDir], { ignoreInitial: true });

  let timer: NodeJS.Timeout | null = null;
  let building = false;
  let pending = false;

  const rebuild = (): void => {
    if (building) {
      pending = true;
      return;
    }
    building = true;
    pending = false;
    try {
      buildSite({ contentDir, outputDir, templatesDir });
      broadcast(wss, RELOAD_MESSAGE);
    } catch (err) {
      console.error('Rebuild failed:', err);
    } finally {
      building = false;
      if (pending) {
        pending = false;
        scheduleRebuild();
      }
    }
  };

  const scheduleRebuild = (): void => {
    if (timer) {
      clearTimeout(timer);
    }
    timer = setTimeout(() => {
      timer = null;
      rebuild();
    }, debounce);
  };

  watcher.on('all', () => scheduleRebuild());

  await new Promise<void>((resolve, reject) => {
    server.once('error', reject);
    server.listen(port, host, () => resolve());
  });

  const address = server.address();
  const actualPort = typeof address === 'object' && address !== null ? address.port : port;

  return {
    server,
    port: actualPort,
    contentDir,
    outputDir,
    templatesDir,
    watcher,
    close(): Promise<void> {
      return new Promise<void>((resolve) => {
        if (timer) {
          clearTimeout(timer);
          timer = null;
        }
        for (const client of wss.clients) {
          client.terminate();
        }
        watcher.close().then(() => {
          wss.close(() => {
            server.close(() => resolve());
          });
        });
      });
    },
  };
}

#!/usr/bin/env node

import { buildSite } from './index';
import { startDevServer } from './serve';

interface CliOptions {
  content?: string;
  output?: string;
  templates?: string;
  port?: string;
}

const VALUE_OPTIONS: Record<string, keyof CliOptions> = {
  '--content': 'content',
  '--output': 'output',
  '--templates': 'templates',
  '--port': 'port',
};

function printHelp(command?: string): void {
  if (command === 'serve') {
    console.log(`Usage: npx ssg serve [options]

Start a live-reload development server.

Options:
  --content <dir>    Content directory containing Markdown files (default: ./content)
  --templates <dir>  Templates directory (default: ./templates)
  --output <dir>     Output directory to build and serve from (default: ./dist)
  --port <port>      Port to listen on (default: 3000)
  -h, --help         Show this help message
`);
    return;
  }

  console.log(`Usage: npx ssg build [options]

Generate a static site from Markdown files.

Options:
  --content <dir>   Content directory containing Markdown files (default: ./content)
  --output <dir>    Output directory for generated HTML (default: ./dist)
  -h, --help        Show this help message

Commands:
  build             Generate a static site from Markdown files
  serve             Start a live-reload development server on localhost:3000
`);
}

function parseArgs(args: string[]): { options: CliOptions; help: boolean } {
  const options: CliOptions = {};
  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    if (arg === '-h' || arg === '--help') {
      return { options, help: true };
    }

    const eq = arg.indexOf('=');
    if (arg.startsWith('--') && eq !== -1) {
      const key = arg.slice(0, eq);
      const value = arg.slice(eq + 1);
      if (!(key in VALUE_OPTIONS)) {
        console.error(`Error: unknown option ${key}`);
        process.exit(2);
      }
      options[VALUE_OPTIONS[key]] = value;
      continue;
    }

    if (arg in VALUE_OPTIONS) {
      const value = args[i + 1];
      if (value === undefined || value.startsWith('--')) {
        console.error(`Error: option ${arg} requires a value`);
        process.exit(2);
      }
      options[VALUE_OPTIONS[arg]] = value;
      i++;
      continue;
    }

    console.error(`Error: unknown option ${arg}`);
    process.exit(2);
  }
  return { options, help: false };
}

function resolvePort(value: string | undefined): number {
  if (value === undefined) {
    return 3000;
  }
  const port = Number(value);
  if (!Number.isInteger(port) || port < 0 || port > 65535) {
    console.error(`Error: invalid port "${value}"`);
    process.exit(2);
  }
  return port;
}

function main(): void {
  const args = process.argv.slice(2);
  const command = args[0];

  if (!command || command === '-h' || command === '--help' || command === 'help') {
    printHelp();
    process.exit(0);
  }

  if (command !== 'build' && command !== 'serve') {
    console.error(`Error: unknown command "${command}"`);
    printHelp();
    process.exit(1);
  }

  const { options, help } = parseArgs(args.slice(1));
  if (help) {
    printHelp(command);
    process.exit(0);
  }

  if (command === 'serve') {
    const port = resolvePort(options.port);
    startDevServer({
      contentDir: options.content ?? 'content',
      outputDir: options.output ?? 'dist',
      templatesDir: options.templates ?? 'templates',
      port,
    })
      .then((server) => {
        console.log(`Serving ${server.outputDir} at http://localhost:${server.port}`);
      })
      .catch((err: Error) => {
        console.error(`Error: ${err.message}`);
        process.exit(1);
      });
    return;
  }

  const site = buildSite({
    contentDir: options.content ?? 'content',
    outputDir: options.output ?? 'dist',
    templatesDir: options.templates ?? 'templates',
  });

  console.log(`Generated ${site.pages.length} page(s) in ${site.outputDir}`);
}

main();

import fs from 'fs';
import http from 'http';
import os from 'os';
import path from 'path';
import WebSocket from 'ws';
import {
  startDevServer,
  injectLiveReloadScript,
  LIVE_RELOAD_SCRIPT,
  RELOAD_MESSAGE,
  DevServer,
} from './serve';

function makeTempDir(): string {
  return fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-serve-'));
}

function get(url: string): Promise<{ status: number; body: string }> {
  return new Promise((resolve, reject) => {
    http
      .get(url, (res) => {
        let body = '';
        res.setEncoding('utf8');
        res.on('data', (chunk) => (body += chunk));
        res.on('end', () => resolve({ status: res.statusCode ?? 0, body }));
      })
      .on('error', reject);
  });
}

function connect(url: string): Promise<WebSocket> {
  return new Promise((resolve, reject) => {
    const ws = new WebSocket(url);
    ws.once('open', () => resolve(ws));
    ws.once('error', reject);
  });
}

function waitForMessage(ws: WebSocket, timeoutMs = 5000): Promise<string> {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error('timed out waiting for message')), timeoutMs);
    ws.once('message', (data) => {
      clearTimeout(timer);
      resolve(data.toString());
    });
  });
}

describe('injectLiveReloadScript', () => {
  it('injects the script before </body>', () => {
    const html = '<html><body><h1>Hi</h1></body></html>';
    const out = injectLiveReloadScript(html);
    expect(out).toContain(LIVE_RELOAD_SCRIPT);
    expect(out.indexOf(LIVE_RELOAD_SCRIPT)).toBeLessThan(out.indexOf('</body>'));
  });

  it('appends the script when there is no </body>', () => {
    const html = '<html><h1>Hi</h1></html>';
    const out = injectLiveReloadScript(html);
    expect(out).toContain(LIVE_RELOAD_SCRIPT);
  });
});

describe('startDevServer', () => {
  let server: DevServer | undefined;

  afterEach(async () => {
    if (server) {
      await server.close();
      server = undefined;
    }
  });

  it('builds and serves pages with the live-reload script injected', async () => {
    const content = makeTempDir();
    const output = makeTempDir();
    fs.writeFileSync(path.join(content, 'hello.md'), '---\ntitle: Hello\n---\n# Hi\n');

    server = await startDevServer({ contentDir: content, outputDir: output, port: 0 });
    const base = `http://127.0.0.1:${server.port}`;

    const index = await get(`${base}/`);
    expect(index.status).toBe(200);
    expect(index.body).toContain(LIVE_RELOAD_SCRIPT);

    const page = await get(`${base}/hello.html`);
